def fill(lots, quantity):
    """Shares taken from each lot, highest cost first, until the quantity is met."""
    taken, remaining = {}, quantity
    for lot in sorted(lots, key=lambda lot: (-lot["cost"], lot["id"])):
        if remaining <= 0:
            break
        take = min(lot["qty"], remaining)
        taken[lot["id"]] = take
        remaining -= take
    return taken

